    resolve_browser_request_input: {
      type: "object",
      properties: {
        request_ref: {
          $ref: "#/$defs/request_ref"
        },
        decision: {
          enum: [
            "confirmed_succeeded",
            "restart_failed"
          ]
        }
      },
      required: [
        "request_ref",
        "decision"
      ],
      additionalProperties: false
    },
    request_resolution_facts: {
      type: "object",
      description: "The succeeded result of the single broker-side target-resolution compare-and-write winner. A restart_failed winner whose three replacement attempts exhaust instead uses a failed ticket with command_restart_exhaustion_facts. A competing resolver must not mutate the browser, terminalize the target, or release its lane and ends failed, never uncertain, with REQUEST_RESOLUTION_RACE_LOST.",
      properties: {
        resolved_request_ref: {
          $ref: "#/$defs/request_ref"
        },
        workspace: {
          $ref: "#/$defs/workspace_fact"
        },
        workspace_active: {
          const: true
        },
        decision: {
          enum: [
            "confirmed_succeeded",
            "restart_failed"
          ]
        },
        resolved_request_state: {
          enum: [
            "succeeded",
            "failed"
          ]
        },
        effect_may_have_occurred: {
          type: [
            "boolean",
            "null"
          ]
        },
        old_tab_ref: {
          $ref: "#/$defs/broker_issued_ref"
        },
        replacement_tab: {
          oneOf: [
            {
              $ref: "#/$defs/tab_fact"
            },
            {
              type: "null"
            }
          ]
        },
        old_tab_remains_managed: {
          type: "boolean"
        },
        replacement_creation_attempts: {
          type: [
            "integer",
            "null"
          ],
          minimum: 1,
          maximum: 3
        },
        reconciled_before_each_retry: {
          type: [
            "boolean",
            "null"
          ]
        },
        invalidated_request_refs: {
          type: "array",
          items: {
            $ref: "#/$defs/request_ref"
          },
          uniqueItems: true
        },
        lane_released: {
          const: true
        }
      },
      required: [
        "resolved_request_ref",
        "workspace",
        "workspace_active",
        "decision",
        "resolved_request_state",
        "effect_may_have_occurred",
        "old_tab_ref",
        "replacement_tab",
        "old_tab_remains_managed",
        "replacement_creation_attempts",
        "reconciled_before_each_retry",
        "invalidated_request_refs",
        "lane_released"
      ],
      additionalProperties: false,
      allOf: [
        {
          properties: {
            workspace: {
              properties: {
                condition: {
                  not: {
                    const: "terminated"
                  }
                }
              }
            }
          }
        },
        {
          if: {
            properties: {
              decision: {
                const: "confirmed_succeeded"
              }
            },
            required: [
              "decision"
            ]
          },
          then: {
            properties: {
              resolved_request_state: {
                const: "succeeded"
              },
              effect_may_have_occurred: {
                type: "null"
              },
              replacement_tab: {
                type: "null"
              },
              old_tab_remains_managed: {
                const: true
              },
              replacement_creation_attempts: {
                type: "null"
              },
              reconciled_before_each_retry: {
                type: "null"
              },
              invalidated_request_refs: {
                maxItems: 0
              }
            }
          },
          else: {
            properties: {
              resolved_request_state: {
                const: "failed"
              },
              effect_may_have_occurred: {
                const: true
              },
              replacement_tab: {
                $ref: "#/$defs/tab_fact"
              },
              old_tab_remains_managed: {
                const: true
              },
              replacement_creation_attempts: {
                type: "integer",
                minimum: 1,
                maximum: 3
              },
              reconciled_before_each_retry: {
                const: true
              }
            }
          }
        }
      ]
    },
